/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeCustDirectDebitMandateCustomerAddress extends GUPPricingAttributeCustDirectDebitMandate implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, CustomerAddress);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::Int64);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by CustomerAddress
    {
        if (! ret.in(custDirectDebitMandate.CustomerAddress))
        {
            ret.add(custDirectDebitMandate.CustomerAddress);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, CustomerAddress));
    qbr.value(queryValue(_value));
}
